import io


class MeteredFile(io.BufferedRandom):
    """Implement using a subclassing model."""

    def __init__(self, *args, **kwargs):
        # counters
        self._read_bytes = 0
        self._read_ops = 0
        self._write_bytes = 0
        self._write_ops = 0

        # Try to initialize like BufferedRandom. If args don't match its signature,
        # try to create a raw FileIO and pass that to BufferedRandom.
        try:
            super().__init__(*args, **kwargs)
        except TypeError:
            raw = io.FileIO(*args, **kwargs)
            super().__init__(raw)

    def __enter__(self):
        # Ensure proper context manager behavior and return the wrapper
        super().__enter__()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        return super().__exit__(exc_type, exc_val, exc_tb)

    def __iter__(self):
        return self

    def __next__(self):
        # Read the next line from the file and count it as a read operation.
        line = super().readline()
        if not line:
            raise StopIteration
        self._read_ops += 1
        try:
            self._read_bytes += len(line)
        except TypeError:
            # len may fail for some types; ignore in that case
            pass
        return line

    def read(self, size=-1):
        data = super().read(size)
        self._read_ops += 1
        if data:
            try:
                self._read_bytes += len(data)
            except TypeError:
                pass
        return data

    @property
    def read_bytes(self):
        return self._read_bytes

    @property
    def read_ops(self):
        return self._read_ops

    def write(self, b):
        n = super().write(b)
        # super().write should return number of bytes written (an int)
        try:
            if isinstance(n, int):
                self._write_bytes += n
            else:
                # Fallback: try to measure length of input if write didn't return count
                self._write_bytes += len(b)
        except Exception:
            pass
        self._write_ops += 1
        return n

    @property
    def write_bytes(self):
        return self._write_bytes

    @property
    def write_ops(self):
        return self._write_ops


class MeteredSocket:
    """Implement using a delegation model."""

    def __init__(self, socket):
        self._socket = socket
        self._recv_bytes = 0
        self._recv_ops = 0
        self._send_bytes = 0
        self._send_ops = 0

    def __enter__(self):
        # Delegate context manager to underlying socket if available,
        # but return the wrapper.
        enter = getattr(self._socket, "__enter__", None)
        if callable(enter):
            enter()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        exitm = getattr(self._socket, "__exit__", None)
        if callable(exitm):
            return exitm(exc_type, exc_val, exc_tb)
        # If underlying socket has close method, close it on exit
        close = getattr(self._socket, "close", None)
        if callable(close):
            close()
        return False

    def recv(self, bufsize, flags=0):
        data = self._socket.recv(bufsize, flags)
        self._recv_ops += 1
        if data:
            try:
                self._recv_bytes += len(data)
            except Exception:
                pass
        return data

    @property
    def recv_bytes(self):
        return self._recv_bytes

    @property
    def recv_ops(self):
        return self._recv_ops

    def send(self, data, flags=0):
        # socket.send may accept flags only on some platforms; handle both forms
        try:
            sent = self._socket.send(data, flags)
        except TypeError:
            # maybe underlying send doesn't accept flags; try without
            sent = self._socket.send(data)
        # sent is number of bytes sent
        try:
            if isinstance(sent, int):
                self._send_bytes += sent
            else:
                self._send_bytes += len(data)
        except Exception:
            pass
        self._send_ops += 1
        return sent

    @property
    def send_bytes(self):
        return self._send_bytes

    @property
    def send_ops(self):
        return self._send_ops
